<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'

type Language={code:string;label:string}
type Course={slug:string;title:string;subject:string;audience:string;description:string;pages:number;minutes:string;languages:Language[]}
const courses:Course[]=[
 {slug:'neural-networks',title:'神经网络基础',subject:'人工智能',audience:'适合人工智能入门学习者',description:'认识生物神经元、M-P 模型和感知机，通过 AND 门示例理解神经元如何形成二元输出。',pages:10,minutes:'约 7 分钟',languages:[{code:'zh-CN',label:'中文'},{code:'ja-JP',label:'日本語'},{code:'ko-KR',label:'한국어'}]},
 {slug:'linear-functions',title:'一次函数与图像',subject:'数学',audience:'适合初学一次函数的学习者',description:'通过简短课程理解一次函数的基本概念，并对比不同语言的课件、语音和字幕。',pages:2,minutes:'约 1 分钟',languages:[{code:'zh-CN',label:'中文'},{code:'en-US',label:'English'},{code:'ja-JP',label:'日本語'},{code:'ko-KR',label:'한국어'},{code:'de-DE',label:'Deutsch'},{code:'fr-FR',label:'Français'}]},
 {slug:'python-list-sum',title:'Python 列表求和',subject:'编程',audience:'适合 Python 初学者',description:'通过列表求和示例学习变量、循环和累加的执行过程。',pages:3,minutes:'约 2 分钟',languages:[{code:'zh-CN',label:'中文'}]},
 {slug:'perceptron',title:'机器学习基础：感知机与二分类',subject:'机器学习',audience:'适合机器学习初学者',description:'从输入、权重和偏置出发，说明感知机如何完成二分类，并用直观例子解释激活函数。',pages:6,minutes:'约 3 分钟',languages:[{code:'zh-CN',label:'中文'},{code:'ja-JP',label:'日本語'},{code:'ko-KR',label:'한국어'}]},
 {slug:'math-animation',title:'数学动画：一次函数斜率',subject:'数学',audience:'适合需要直观理解数学变化的学习者',description:'通过动画观察斜率变化，连接公式、图像和实际变化率。',pages:6,minutes:'约 2 分钟',languages:[{code:'zh-CN',label:'中文'}]},
 {slug:'pdf-course',title:'教师示例：PDF 课件转课程',subject:'教师工具',audience:'适合教师了解课程制作流程',description:'查看从 PDF 导入、页面解析到视频、讲稿和可编辑课件输出的完整示例。',pages:6,minutes:'约 2 分钟',languages:[{code:'zh-CN',label:'中文'}]}
]
const route=useRoute()
const selectedSlug=ref('')
const selectedLanguage=ref('zh-CN')
const query=ref('')
const subjectFilter=ref('全部')
const selected=computed(()=>courses.find(item=>item.slug===selectedSlug.value))
const subjects=computed(()=>['全部',...Array.from(new Set(courses.map(item=>item.subject)))])
const filteredCourses=computed(()=>courses.filter(item=>{
 const text=`${item.title}${item.subject}${item.description}`.toLowerCase()
 return (subjectFilter.value==='全部'||item.subject===subjectFilter.value)&&(!query.value.trim()||text.includes(query.value.trim().toLowerCase()))
}))
watch(()=>String(route.query.course||''),value=>{selectedSlug.value=courses.some(item=>item.slug===value)?value:'';selectedLanguage.value='zh-CN'},{immediate:true})
watch(selectedSlug,()=>{selectedLanguage.value='zh-CN'})
const base=computed(()=>selected.value?`/public-courses/${selected.value.slug}/${selectedLanguage.value}`:'')
function open(course:Course){selectedSlug.value=course.slug;selectedLanguage.value='zh-CN'}
</script>
<template>
 <div class="public-library">
  <nav class="mooc-topnav"><strong>智课工坊公开课</strong><span>课程首页</span><span>课程分类</span><span>学习资料</span><span class="topnav-space"></span><small>面向教师与学习者的 AI 课程空间</small></nav>
  <section class="library-hero"><div><p class="eyebrow">SMARTCOURSE OPEN CLASS</p><h1>把好课程直接带进课堂</h1><p>浏览已完成的公开课，直接观看视频、切换语言，并下载课件、讲稿和字幕。</p><div class="hero-actions"><a href="#course-catalog">浏览课程</a><a class="secondary" href="/acceptance-report.html" target="_blank">查看验收结果</a></div></div><div class="hero-visual"><span class="hero-play">▶</span><div class="hero-sheet"><small>OPEN COURSE</small><strong>神经网络<br>基础</strong><span>中文 · 日本語 · 한국어</span></div></div></section>
  <template v-if="!selected">
   <div id="course-catalog" class="catalog-head"><div><p class="eyebrow">COURSE CATALOG</p><h2>公开课程目录</h2><p>按主题和关键词查找适合课堂演示的课程。</p></div><div class="catalog-count"><strong>{{filteredCourses.length}}</strong><span>门课程</span></div></div>
   <div class="catalog-toolbar"><div class="subject-filter"><button v-for="subject in subjects" :key="subject" :class="{active:subjectFilter===subject}" @click="subjectFilter=subject">{{subject}}</button></div><input v-model="query" aria-label="搜索公开课程" placeholder="搜索课程名称或内容" /></div>
   <div class="library-grid">
    <article v-for="course in filteredCourses" :key="course.slug" class="library-card">
     <div class="library-cover" :class="`cover-${course.slug}`"><span>{{course.subject}}</span><strong>{{course.title}}</strong><small>{{course.audience}}</small><i>▶</i></div>
     <div class="library-body"><p>{{course.description}}</p><div class="course-meta"><span>{{course.pages}} 页</span><span>{{course.minutes}}</span><span>{{course.languages.length}} 种语言</span></div><div class="language-tags"><span v-for="language in course.languages" :key="language.code">{{language.label}}</span></div><button class="primary-action" @click="open(course)">查看课程</button></div>
    </article>
   </div>
   <div v-if="!filteredCourses.length" class="empty-catalog">没有找到匹配的课程，请更换关键词或主题。</div>
  </template>
  <div v-else class="course-detail">
   <button class="back-button" @click="selectedSlug=''">返回课程目录</button>
   <div class="detail-heading"><div><p class="eyebrow">{{selected.subject}} · OPEN COURSE</p><h2>{{selected.title}}</h2><p>{{selected.description}}</p><div class="detail-meta"><span>{{selected.audience}}</span><span>{{selected.pages}} 页</span><span>{{selected.minutes}}</span><span>{{selected.languages.length}} 种语言</span></div></div><div class="detail-badge">已完成课程<br><small>可直接观看</small></div></div>
   <div class="language-selector"><span>课程语言</span><button v-for="language in selected.languages" :key="language.code" :class="{active:selectedLanguage===language.code}" @click="selectedLanguage=language.code">{{language.label}}</button></div>
   <div class="course-video-shell"><img class="course-poster" :src="base+'/preview/pages/slide_001.png'" alt="课程视频封面"><span class="poster-play">▶</span><a class="video-open" :href="base+'/course.mp4'" target="_blank">打开完整视频</a></div>
   <div class="download-links"><a :href="base+'/course.pdf'" target="_blank">查看课件 PDF</a><a :href="base+'/lecture.txt'" target="_blank">查看讲稿</a><a :href="base+'/subtitles.srt'" target="_blank">查看字幕</a><a :href="base+'/course.pptx'" download>下载可编辑 PPTX</a><a :href="base+'/course.mp4'" download>下载视频</a></div>
  </div>
 </div>
</template>
